int cipso_v4_doi_add_tags(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int i, num_tags = 0;

    attr = info->attrs[ATTR_CIPSO_TAG];
    if (!attr)
        return -EINVAL;

    for (i = 0; i < MAX_CIPSO_TAGS; i++) {
        if (!nla_len(attr))
            break;

        if (nla_type(attr) != NLA_U8)
            return -EINVAL;

        doi_def->tags[i] = nla_get_u8(attr);
        nla_next(attr, &info->attrs[ATTR_CIPSO_TAG]);
        num_tags++;
    }

    if (num_tags >= MAX_CIPSO_TAGS)
        return -EINVAL;

    while (num_tags < MAX_CIPSO_TAGS)
        doi_def->tags[num_tags++] = CIPSO_V4_INVALID_TAG;

    return 0;
}

int cipso_v4_doi_add_common(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int i, num_tags = 0;
    int max_tags = CIPSO_V4_TAG_MAX;
    int rc = 0;

    if (!info || !doi_def)
        return -EINVAL;

    attr = info->attrs[CIPSO_V4_ATTR_TAG_LIST];
    if (!attr)
        return -EINVAL;

    num_tags = nla_len(attr) / sizeof(__u16);
    if (num_tags > max_tags)
        return -EINVAL;

    for (i = 0; i < num_tags; i++) {
        __u16 tag = *(__u16 *)nla_data(attr) + i;
        if (tag >= CIPSO_V4_TAG_MAX) {
            return -EINVAL;
        }
        doi_def->tags[i] = tag;
    }

    for (; i < max_tags; i++) {
        doi_def->tags[i] = CIPSO_V4_TAG_INVALID;
    }

    return rc;
}

int cipso_v4_doi_add_tags(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int rem;

    if (!info || !doi_def)
        return -EINVAL;

    doi_def->doi = nla_get_u32(genl_info_attr(info, CIPSO_V4_ATTR_DOI));

    nla_for_each_attr(attr, genl_info_data(info), genl_info_len(info), rem) {
        u8 tag;

        if (doi_def->num_tags >= CIPSO_V4_TAG_MAX) {
            memset(&doi_def->tags[doi_def->num_tags], 0xff,
                   (CIPSO_V4_TAG_MAX - doi_def->num_tags) *
                   sizeof(doi_def->tags[0]));
            return 0;
        }

        tag = nla_get_u8(attr);
        if (tag >= CIPSO_V4_TAG_MAX)
            return -EINVAL;

        doi_def->tags[doi_def->num_tags++] = tag;
    }

    if (doi_def->num_tags >= CIPSO_V4_TAG_MAX)
        return 0;

    memset(&doi_def->tags[doi_def->num_tags], 0xff,
           (CIPSO_V4_TAG_MAX - doi_def->num_tags) *
           sizeof(doi_def->tags[0]));

    return 0;
}

int cipso_v4_doi_add_common(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int i = 0, rem;
    int ret = 0;

    if (!info || !doi_def)
        return -EINVAL;

    nla_for_each_attr(attr, info->attrs, info->nlhdr->nlmsg_len - GENL_HDRLEN, rem) {
        if (i >= CIPSO_V4_DOI_MAX_TAGS) {
            ret = -EINVAL;
            break;
        }

        doi_def->tags[i++] = nla_get_u8(attr);
    }

    if (ret == 0 && i >= CIPSO_V4_DOI_MAX_TAGS)
        ret = -EINVAL;

    while (i < CIPSO_V4_DOI_MAX_TAGS)
        doi_def->tags[i++] = CIPSO_V4_TAG_INVALID;

    return ret;
}

int cipso_v4_doi_add_common(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int i, num_tags = 0;
    int max_tags = CIPSO_V4_TAG_MAX;

    attr = nla_find(info->attrs, CIPSO_V4_ATTR_TAGS);
    if (!attr)
        return -EINVAL;

    for (i = 0; i < max_tags; i++) {
        struct nlattr *tag_attr = nla_find_nested(attr, i + 1);

        if (!tag_attr)
            break;

        if (nla_len(tag_attr) != sizeof(u8))
            return -EINVAL;

        doi_def->tags[i] = nla_get_u8(tag_attr);
        num_tags++;
    }

    if (num_tags >= max_tags)
        return -EINVAL;

    while (i < max_tags)
        doi_def->tags[i++] = CIPSO_V4_TAG_INVALID;

    return 0;
}
